//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");

//#include("../js/controlResize.js"); // 화면 리사이징

scwin.vScrenID = 'ULDSTF34100.xml';
scwin.todat = "";
scwin.gEmpNo = js_emp_no;
scwin.gIsurCd;
scwin.gIsurNm;
scwin.gToday;
scwin.filter_cnt = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //filter된 법인목록

scwin.fn_SetCode = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_today_dd.setValue(vCurDate);
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);

    // tab3지정자문인 목록
    dts_DESIGN_ADVSER.DataID = "/ListedCompany.do?method=listDesignAdviser" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_DESIGN_ADVSER.Reset();
};


//tab3 목록
scwin.fn_srhTab3 = function() {
    var url_list = "/ListedCompany.do?method=schDircDsclSatisfact&inputMessageId=DIRC_DISCLS_SATISFACT_INOUT" + "&outputMessageId=DIRC_DISCLS_SATISFACT_INOUT";
    var url_cond = "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&DESIGN_ISUR_CD=" + $c.stf.getObjectValue(cmb_DESIGN_ADVSER) + "&SATISFACT_YN=" + $c.stf.getObjectValue(cmb_APPL_RSLT) + "&TODAY_DD=" + $c.stf.getObjectValue(edt_today_dd) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    // 그리드의 데이타 조회
    dts_tab3.DataID = encodeURI(url_list + url_cond);
    dts_tab3.reset();
    $c.cm.ShowWin(grd_tab3);
};


//더블클릭 시 변수값 셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gIsurCd = dts_tab3.getCellData(eval(obj), "ISUR_CD"); //회사코드
    scwin.gIsurNm = dts_tab3.getCellData(eval(obj), "COM_ABBRV"); //회사명
    scwin.gToday = $c.stf.getObjectValue(edt_today_dd);
};
scwin.fn_toDate = function() {
    var clientnow = new Date();
    /* 오늘 날짜를 구한다 */
    var curYear = clientnow.getYear();
    var curMonth = (clientnow.getMonth()) + 1;
    var curDay = clientnow.getDate();
    if (curMonth <= 9) {
        curMonth = "0" + curMonth;
    }
    if (curDay <= 9) {
        curDay = "0" + curDay;
    }
    movingtime = curYear + "" + curMonth + "" + curDay;
    scwin.todat = movingtime;
    edt_strt_dd.setValue(scwin.todat); //탭2

};
scwin.fn_list_all = function() {
    var url_list = "/ListedCompany.do?method=searchDircDisclsSysStat&inputMessageId=DIRC_DISCLS_SYS_LIST_INOUT" + "&outputMessageId=DIRC_DISCLS_SYS_LIST_INOUT";
    var url_cond = "&SPOT_ISU_TRD_MKT_TP_CD=6" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    // 그리드의 데이타 조회
    MxDataSet_List1.DataID = encodeURI(url_list + url_cond);
    MxDataSet_List1.reset();
    //ShowWin(grd_Grid);

};
scwin.fn_list_history = function(sval) {
    var url_list = "/ListedCompany.do?method=searchIssueDircDisclsSysHistory&inputMessageId=DIRC_DISCLS_SYS_LIST_INOUT" + "&outputMessageId=DIRC_DISCLS_SYS_LIST_INOUT";
    var url_cond = "&ISUR_CD=" + sval + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    // 그리드의 데이타 조회
    MxDataSet_List2.DataID = encodeURI(url_list + url_cond);
    MxDataSet_List2.reset();
    //ShowWin(grd_Grid);

};
scwin.fn_list_listing = function() {
    var url_list = "/ListedCompany.do?method=searchListingDircDisclsSys&inputMessageId=DIRC_DISCLS_SYS_LIST_INOUT" + "&outputMessageId=DIRC_DISCLS_SYS_LIST_INOUT";
    var url_cond = "&SPOT_ISU_TRD_MKT_TP_CD=6" + "&LIST_STAT_CD=Y" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    // 그리드의 데이타 조회
    MxDataSet_List3.DataID = encodeURI(url_list + url_cond);
    MxDataSet_List3.reset();
};




/*----------------------------------------------------------------------------
	** 데이터셋의 체크박스 선택이 되어 있는지 확인하여 참,거짓을 넘겨준다. 
-------------------------------------------------------------------------------*/
scwin.fn_cntDatasetRowCheck = function(sval) {
    cCnt = 0;
    for (i = 1; i <= sval.getTotalRow(); i++) {
        //alert(sval.NameValue(i, "CHK_FLAG"));
        if (sval.getCellData(i, "CHK_FLAG") == 1) {
            cCnt++;
        }
    }
    if (cCnt == 0) {
        return false;
    } else {
        return true;
    }
};
scwin.fn_chk_cancle = function(sval) {
    //데이터셋 체크박스 초기화
    for (var i = 1; i <= sval.getTotalRow(); i++) {
        sval.setCellData(i, "CHK_FLAG", 0);
    }
};
scwin.fn_undo = function(sval) {
    sval.undoall();
};


/********************************************** 
 * 함수명   : JongmokSearch()
 * 설명       : 종목명검색
 ***********************************************/
scwin.skw = "";
scwin.JongmokSearch = function() {
    scwin.skw = (txb_jongmokName.getValue()).toUpperCase();
    if (scwin.skw == "") {
        //true를 먼저 안해주면 false가 안먹네...
        MxDataSet_List1.UseFilter = "true";
        MxDataSet_List1.Filter();
        MxDataSet_List1.UseFilter = "false";
        MxDataSet_List1.setRowPosition(1, 0);
    } else {
        MxDataSet_List1.UseFilter = "true";
        MxDataSet_List1.Filter();
        MxDataSet_List1.setRowPosition(1, 0);
    }
};
scwin.resetMxDataSet_List4 = function() {
    MxDataSet_List4.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DIRC_DISCLS_SYS_LIST_INOUT";
    MxDataSet_List4.reset();
};



// 저장
scwin.fn_save = function() {
    if (!scwin.fn_cntDatasetRowCheck(MxDataSet_List4)) {
        $c.win.alert("체크된 종목이 없습니다.");
        return;
    } else {
        for (var i = 1; i <= MxDataSet_List4.getTotalRow(); i++) {
            if (MxDataSet_List4.getCellData(i, "CHK_FLAG") == 1) {
                if (scwin.fn_getDircDisclsSysCheck(i, MxDataSet_List4, MxDataSet_List4.getCellData(i, "ISUR_CD"), "save", MxDataSet_List4.getCellData(i, "DIRC_DISCLS_SYS_YN"))) {

                } else {
                    return false;
                }
            }
        }
    }
    var vAnswer = confirm("저장 하시겠습니까?");
    if (vAnswer == true) {
        trs_insert.Action = "/ListedCompany.do?method=saveDircDisclsSys&inputMessageId=DIRC_DISCLS_SYS_LIST_INOUT";
        trs_insert.KeyName = "toinb_dataid4";
        trs_insert.KeyValue = "JSP(I:pInput=MxDataSet_List4)";
        trs_insert.Post();
    }
};






// 선택
scwin.fn_Confirm = function() {
    var total = 0;
    var dircDisclsSysYnNm;
    var dircDisclsSysYn;
    for (var i = 1; i <= MxDataSet_List3.getTotalRow(); i++) {
        var chk = MxDataSet_List3.getCellData(i, "CHK_FLAG");
        if (chk == "T" || chk == 1) total++;
    }
    if ($c.stf.getObjectValue(cmb_select) == "S") {
        $c.win.alert("직접공시제 지정·해제를 선택하세요.");
        cmb_select.focus();
        return false;
    } else if ($c.stf.getObjectValue(cmb_select) == "Y") {
        dircDisclsSysYnNm = "지정";
        dircDisclsSysYn = "Y";
    } else if ($c.stf.getObjectValue(cmb_select) == "N") {
        dircDisclsSysYnNm = "해제";
        dircDisclsSysYn = "N";
    } else {
        return false;
    }
    if (total == 0) {
        $c.win.alert("종목을 선택하세요.");
        return false;
    }
    var vStrt_dd = $c.stf.getObjectValue(edt_strt_dd);
    MxDataSet_List4.setBroadcast(false);
    var j = 1 + MxDataSet_List4.getTotalRow();
    for (var i = 1; i <= MxDataSet_List3.getTotalRow(); i++) {
        var chk = MxDataSet_List3.getCellData(i, "CHK_FLAG");
        if (chk == "T" || chk == 1) {
            if (scwin.fn_getDircDisclsSysCheck(i, MxDataSet_List3, MxDataSet_List3.getCellData(i, "ISUR_CD"), "check", "")) {
                MxDataSet_List4.insertRow();
                MxDataSet_List4.setCellData(j, "CHK_FLAG", "T");
                MxDataSet_List4.setCellData(j, "CHK_FLAG", 1);
                MxDataSet_List4.setCellData(j, "ISUR_CD", MxDataSet_List3.getCellData(i, "ISUR_CD"));
                MxDataSet_List4.setCellData(j, "COM_ABBRV", MxDataSet_List3.getCellData(i, "COM_ABBRV"));
                MxDataSet_List4.setCellData(j, "DESIGN_ADVSER_COM_ABBRV", MxDataSet_List3.getCellData(i, "DESIGN_ADVSER_COM_ABBRV"));
                MxDataSet_List4.setCellData(j, "DIRC_DISCLS_SYS_YN_NM", dircDisclsSysYnNm);
                MxDataSet_List4.setCellData(j, "DIRC_DISCLS_SYS_YN", dircDisclsSysYn);
                MxDataSet_List4.setCellData(j, "REG_ID", scwin.gEmpNo);
                MxDataSet_List4.setCellData(j, "DESIGN_DD", vStrt_dd);
                j++;
            } else {
                //resetMxDataSet_List4();
                return false;
            }
        }
    }
    MxDataSet_List4.setBroadcast(true);
    scwin.fn_chk_cancle(MxDataSet_List3);
    return true;
};




// 직접공시제 체크
scwin.fn_getDircDisclsSysCheck = function(num, obj, val, gbn, yn) {
    var vDIRC_DISCLS_SYS_YN;
    var vDIRC_DISCLS_SYS_DD;
    var vDIRC_DISCLS_SYS_YN_NM;
    var url_list = "/ListedCompany.do?method=getDircDisclsSysCheck&inputMessageId=DIRC_DISCLS_SYS_LIST_INOUT" + "&outputMessageId=DIRC_DISCLS_SYS_LIST_INOUT";
    var url_cond = "&ISUR_CD=" + val + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    // 그리드의 데이타 조회
    dts_check.DataID = encodeURI(url_list + url_cond);
    dts_check.reset();
    vDIRC_DISCLS_SYS_YN = dts_check.getCellData(1, "DIRC_DISCLS_SYS_YN");
    vDIRC_DISCLS_SYS_DD = dts_check.getCellData(1, "DIRC_DISCLS_SYS_DD");
    if (vDIRC_DISCLS_SYS_YN == "Y") {
        vDIRC_DISCLS_SYS_YN_NM = "지정";
    } else if (vDIRC_DISCLS_SYS_YN == "N") {
        vDIRC_DISCLS_SYS_YN_NM = "해제";
    } else {

    }
    var vStrt_dd = $c.stf.getObjectValue(edt_strt_dd);
    if (vStrt_dd == '') {
        $c.win.alert("지정·해제일자를 선택하세요");
        edt_strt_dd.focus();
        return;
    }
    if (vStrt_dd < $c.ut.cGetToday("yyyymmdd")) {
        $c.win.alert("지정·해제일자를 오늘 날짜 이후로 지정하세요");
        edt_strt_dd.focus();
        return;
    }
    if (obj.getCellData(num, "CHK_FLAG") == 1) {
        if (vDIRC_DISCLS_SYS_DD >= vStrt_dd) {
            $c.win.alert("'" + obj.getCellData(num, "COM_ABBRV") + "' 의 " + vDIRC_DISCLS_SYS_YN_NM + " 일자 이후로 지정해주세요");
            scwin.fn_chk_cancle(obj);
            scwin.fn_list_listing();
            return false;
        }
    }

    //for (var i = 1;i <=obj.CountRow ;i++) {
    /*	if(obj.NameValue(num, "CHK_FLAG") == 1) {		
    		if(vDIRC_DISCLS_SYS_DD == todat){
    			alert("'"+obj.NameValue(num,"COM_ABBRV") + "' 는(은) 오늘 이미 " + vDIRC_DISCLS_SYS_YN_NM + " 되었습니다.");
    			fn_chk_cancle(obj);
    			fn_list_listing();
    			return false;
    		}
    	}*/
    //}

    if (gbn == "check") {
        // 선택일때
        if ($c.stf.getObjectValue(cmb_select) == 'S') {
            $c.win.alert("직접공시제 지정·해제를 선택하세요.");
            scwin.fn_chk_cancle(MxDataSet_List3);
            cmb_select.focus();
            return false;
            // 지정일때
        } else if ($c.stf.getObjectValue(cmb_select) == 'Y') {
            if (vDIRC_DISCLS_SYS_YN == "Y") {
                $c.win.alert("이미 지정된 상태입니다.");
                scwin.fn_chk_cancle(MxDataSet_List3);
                return false;
            } else {
                return true;
            }
            // 해제일때

        } else if ($c.stf.getObjectValue(cmb_select) == 'N') {
            // 데이터가 없으면 통과
            if (vDIRC_DISCLS_SYS_YN == undefined) {
                $c.win.alert("미지정 상태로 해제할 수 없습니다.");
                scwin.fn_chk_cancle(MxDataSet_List3);
                return false;
            } else if (vDIRC_DISCLS_SYS_YN == "N") {
                $c.win.alert("이미 해제된 상태입니다.");
                scwin.fn_chk_cancle(MxDataSet_List3);
                return false;
            } else {
                return true;
            }
        } else {
            return true;
        }
    } else {
        if (yn == "Y") {
            if (vDIRC_DISCLS_SYS_YN == "Y") {
                $c.win.alert("이미 지정된 상태입니다.");
                return false;
            }
            return true;
        } else if (yn == "N") {
            if (vDIRC_DISCLS_SYS_YN == "N") {
                $c.win.alert("이미 해제된 상태입니다.");
                return false;
            }
            return true;
        } else {
            return true;
        }
    }
};
scwin.grd_List4_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.grd_List3_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.MxTab_OnSelChanged = function(nIndex) {
    if (nIndex == 1) {
        // 탭인덱스 1  : 직접공시제 지정기업 현황
        scwin.fn_list_all();
    } else if (nIndex == 2) {
        //탭인덱스 2 : 직접공시제 기업 지정
        scwin.fn_list_listing();
    } else if (nIndex == 3) {
        //탭인덱스 3 : 직접공시제 요건 확인
        scwin.fn_srhTab3();
    }
};
scwin.MxDataSet_List1_OnFilter = function(row) {
    lst_gubun = rdo_gubun.getValue();
    f3 = MxDataSet_List1.getCellData(row, "LIST_STAT_CD");
    if (scwin.skw != "") {
        f1 = MxDataSet_List1.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_List1.getCellData(row, "OLD_COM_ABBRV");
        if (lst_gubun == 0) {
            if (f1.indexOf(scwin.skw) != -1) {
                scwin.filter_cnt++;
                return true;
            } else if (f2.indexOf(scwin.skw) != -1) {
                scwin.filter_cnt++;
                return true;
            } else {
                return false;
            }
        } else {
            if (f1.indexOf(scwin.skw) != -1 && f3.indexOf(lst_gubun) != -1) {
                scwin.filter_cnt++;
                return true;
            } else if (f2.indexOf(scwin.skw) != -1 && f3.indexOf(lst_gubun) != -1) {
                scwin.filter_cnt++;
                return true;
            } else {
                return false;
            }
        }
    } else {
        if (lst_gubun == 0) {
            scwin.filter_cnt++;
            return true;
        } else if (f3.indexOf(lst_gubun) != -1) {
            scwin.filter_cnt++;
            return true;
        } else {
            return false;
        }
    }
};
scwin.MxDataSet_List1_OnRowsetChanged = function() {
    cnt1.setValue(scwin.filter_cnt + " 종목");
};
scwin.MxDataSet_List1_OnLoadCompleted = function(rowcount) {
    cnt1.setValue(rowcount + " 종목");
};
scwin.MxDataSet_List2_OnLoadCompleted = function(rowcount) {
    cnt2.setValue(rowcount + " 이력");
};
scwin.MxDataSet_List3_OnLoadCompleted = function(rowcount) {
    cnt3.setValue(rowcount + " 종목");
    //cnt1.value = rowcount+" 종목";

};
scwin.trs_insert_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
    scwin.resetMxDataSet_List4();
    scwin.fn_list_all();
    scwin.fn_list_listing();
};
scwin.trs_insert_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장"));
    $c.win.alert(trs_insert.ErrorMsg);
    scwin.resetMxDataSet_List4();
};
scwin.btn_select_onclick = function() {
    scwin.fn_Confirm();
};
scwin.btn_excel_down_onclick = function() {
    $c.data.downloadGridViewExcel(grd_Grid, "직접공시제 지정기업 현황", "", "2");
};
scwin.btn_refresh_onclick = function() {
    scwin.fn_list_all();
    scwin.fn_list_listing();
    scwin.resetMxDataSet_List4();
    $c.stf.setObjectValue(cmb_select, "S");
};
scwin.grd_Grid_OnClick = function(row, colid) {
    iscd = MxDataSet_List1.getCellData(row, "ISUR_CD");
    scwin.fn_list_history(iscd);
};
scwin.grd_List3_OnCheckClick = function(col, colid, bCheck) {
    if (MxDataSet_List3.getCellData(col, "CHK_FLAG") == 1) {
        // 현재 종목의 지정 여부 체크
        if (scwin.fn_getDircDisclsSysCheck(col, MxDataSet_List3, MxDataSet_List3.getCellData(col, "ISUR_CD"), "check", "")) {
            // 선택된 종목 체크
            for (var i = 1; i <= MxDataSet_List4.getTotalRow(); i++) {
                if (MxDataSet_List4.getCellData(i, "ISUR_CD") == MxDataSet_List3.getCellData(col, "ISUR_CD")) {
                    $c.win.alert("이미 선택된 종목입니다.");
                    scwin.fn_chk_cancle(MxDataSet_List3);
                    return false;
                }
            }
        } else {
            return false;
        }
    }
};
scwin.grd_List3_OnHeadCheckClick = function(col, colid, bCheck) {
    var gcnt = MxDataSet_List3.getTotalRow();
    if (gcnt > 0) {
        grd_List3.Redraw = false;
        for (var i = 1; i <= gcnt; i++) {
            MxDataSet_List3.setCellData(i, "CHK_FLAG", bCheck);
        }
        grd_List3.Redraw = true;
    }
};
scwin.grd_List4_OnHeadCheckClick = function(col, colid, bCheck) {
    var gcnt = MxDataSet_List4.getTotalRow();
    if (gcnt > 0) {
        grd_List4.Redraw = false;
        for (var i = 1; i <= gcnt; i++) {
            MxDataSet_List4.setCellData(i, "CHK_FLAG", bCheck);
        }
        grd_List4.Redraw = true;
    }
};
scwin.txb_jongmokName_onkeydown = function() {
    if (window.event.keyCode == "13") {
        scwin.filter_cnt = 0;
        //JongmokName(window.event.keyCode);
        scwin.JongmokSearch();
    }
};
scwin.bnt_save_onclick = function() {
    scwin.fn_save();
};
scwin.rdo_gubun_OnSelChange = function() {
    scwin.filter_cnt = 0;
    MxDataSet_List1.UseFilter = "true";
    MxDataSet_List1.Filter();
    MxDataSet_List1.setRowPosition(1, 0);
};
scwin.dts_check_OnLoadCompleted = function(rowcount) {
    //fn_check( dts_btnshow.NameString(1, "ISUR_CD" ), dts_btnshow.NameString(1, "DIRC_DISCLS_SYS_YN" ));	

};
scwin.dts_check_OnLoadError = function() {
    //alert('dts_btnshow.OnFail() :' + dts_btnshow.ErrorMsg);

};
scwin.cmb_select_OnSelChange2 = function() {

