    if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    } else if (colid == "NFAITHDISCLS_CORP_YN") {
        var url = "/dsclmgt/ULDSTF35107.gfm";
        var winTitle = "불성실공시법인 ";
        //frame.CreateDialogFrame("", url , winTitle ,100, 10,1270, 750, "window" );	
        $c.frame.path("/top").WinOpen("CORP", url + "?" + frame.FrameID, winTitle, 1100, 750);
    } else if (colid == "DISCLS_PNT") {
        var url = "/issueinfo/ULDSTF34101.gfm";
        var winTitle = "공시실적 점수 조회 ";
        //frame.CreateDialogFrame("공시실적 점수 조회", url , winTitle ,100, 10,1100, 750, "window" );	
        $c.frame.path("/top").WinOpen("PNT", url + "?" + frame.FrameID, winTitle, 1100, 750);
    }
};
